<div class="admin-page-head"><div><span class="eyebrow">CONFIGURARE</span><h1>Setări</h1><p>Tot ce are nevoie magazinul, fără editare de cod.</p></div></div><nav class="settings-tabs"><button class="active" data-settings-tab="general">General</button><button data-settings-tab="homepage">Homepage</button><button data-settings-tab="livrare">Livrare</button><button data-settings-tab="plati">Plăți</button><button data-settings-tab="email">Email</button><button data-settings-tab="seo">SEO</button><button data-settings-tab="social">Social</button></nav><form class="settings-panel active" id="general" action="/admin/setari" method="post" enctype="multipart/form-data"><?=csrf_field()?><section class="admin-card"><h2>Identitatea magazinului</h2><div class="admin-form-grid"><label>Nume site<input name="site_name" value="<?=e($settings['site_name']??'SmileBaby')?>"></label><label>Email<input type="email" name="site_email" value="<?=e($settings['site_email']??'')?>"></label><label>Telefon<input name="site_phone" value="<?=e($settings['site_phone']??'')?>"></label><label>Adresă<input name="site_address" value="<?=e($settings['site_address']??'')?>"></label><label>Logo<input type="file" name="logo" accept="image/*"></label><label>Favicon<input type="file" name="favicon" accept="image/*"></label></div><button class="admin-button">Salvează setările</button></section></form><form class="settings-panel" id="homepage" action="/admin/setari" method="post" enctype="multipart/form-data"><?=csrf_field()?><section class="admin-card"><h2>Hero</h2><label>Etichetă<input name="hero_eyebrow" value="<?=e($settings['hero_eyebrow']??'')?>"></label><label>Titlu<input name="hero_title" value="<?=e($settings['hero_title']??'')?>"></label><label>Descriere<textarea name="hero_description" rows="4"><?=e($settings['hero_description']??'')?></textarea></label><div class="admin-form-grid"><label>Text buton<input name="hero_cta_label" value="<?=e($settings['hero_cta_label']??'')?>"></label><label>Link buton<input name="hero_cta_url" value="<?=e($settings['hero_cta_url']??'')?>"></label><label>Imagine hero<input type="file" name="hero_image" accept="image/*"></label></div><h2>Despre SmileBaby</h2><label>Titlu<input name="about_title" value="<?=e($settings['about_title']??'')?>"></label><label>Text<textarea name="about_text" rows="5"><?=e($settings['about_text']??'')?></textarea></label><label>Imagine<input type="file" name="about_image" accept="image/*"></label><label>Citat<textarea name="home_quote" rows="3"><?=e($settings['home_quote']??'')?></textarea></label><button class="admin-button">Salvează homepage</button></section></form><form class="settings-panel" id="livrare" action="/admin/setari" method="post"><?=csrf_field()?><section class="admin-card"><h2>Livrare</h2><input type="hidden" name="shipping_enabled" value="0"><label class="switch-row"><span><strong>Livrare activă</strong><small>Permite calcularea costului la checkout.</small></span><input type="checkbox" name="shipping_enabled" value="1" <?=($settings['shipping_enabled']??'1')?'checked':''?> role="switch"><i></i></label><div class="admin-form-grid"><label>Cost standard<input type="number" step="0.01" name="standard_shipping_cost" value="<?=e($settings['standard_shipping_cost']??20)?>"></label><label>Gratuit peste<input type="number" step="0.01" name="free_shipping_threshold" value="<?=e($settings['free_shipping_threshold']??300)?>"></label><label>Estimare livrare<input name="estimated_delivery_text" value="<?=e($settings['estimated_delivery_text']??'2–3 zile lucrătoare')?>"></label></div><button class="admin-button">Salvează livrarea</button></section></form><section class="settings-panel" id="plati"><div class="payment-warning" <?=count(array_filter($methods,fn($m)=>$m['enabled']))?'hidden':''?>>Nu există nicio metodă de plată activă. Clienții nu pot finaliza comenzi.</div><div class="payment-admin-grid"><?php foreach($methods as $method):?><form class="admin-card payment-admin-card" action="/admin/setari/plati/<?=e($method['key'])?>" method="post"><?=csrf_field()?><div class="payment-card-head"><div class="payment-icon"><?= $method['key']==='cash_on_delivery'?icon('truck'):($method['key']==='online_card'?icon('card'):icon('gift')) ?></div><div><h2><?=e($method['name'])?></h2><span class="payment-health"><?= $method['key']==='online_card'?(($method['settings']['merchant_id']??'')?'Configurat':'Necorespunzător'):'Configurat' ?></span></div><label class="switch-row compact"><input type="checkbox" name="enabled" value="1" <?=$method['enabled']?'checked':''?> role="switch"><i></i><span class="sr-only">Activ</span></label></div><label>Nume afișat<input name="name" value="<?=e($method['name'])?>"></label><label>Descriere<textarea name="description" rows="2"><?=e($method['description'])?></textarea></label><div class="admin-form-grid"><label>Taxă<select name="fee_type"><option value="none">Fără taxă</option><option value="fixed" <?=$method['fee_type']==='fixed'?'selected':''?>>Fixă</option><option value="percentage" <?=$method['fee_type']==='percentage'?'selected':''?>>Procent</option></select></label><label>Valoare<input type="number" step="0.01" min="0" name="fee_value" value="<?=e($method['fee_value'])?>"></label><label>Comandă minimă<input type="number" step="0.01" name="minimum_order" value="<?=e($method['minimum_order'])?>"></label><label>Comandă maximă<input type="number" step="0.01" name="maximum_order" value="<?=e($method['maximum_order'])?>"></label><label>Ordine<input type="number" name="sort_order" value="<?=e($method['sort_order'])?>"></label></div><label>Instrucțiuni<textarea name="instructions" rows="3"><?=e($method['instructions'])?></textarea></label><?php if($method['key']==='online_card'):?><details><summary>Configurare procesator</summary><div class="admin-form-grid"><label>Provider<select name="provider"><?php foreach(['netopia'=>'Netopia','stripe'=>'Stripe','euplatesc'=>'EuPlătesc','payu'=>'PayU','other'=>'Other'] as $v=>$l):?><option value="<?=$v?>" <?=($method['settings']['provider']??'')===$v?'selected':''?>><?=$l?></option><?php endforeach?></select></label><label class="switch-row compact"><span><strong>Mod test</strong></span><input type="checkbox" name="test_mode" value="1" <?=!empty($method['settings']['test_mode'])?'checked':''?> role="switch"><i></i></label><label>Merchant ID<input name="merchant_id" value="<?=e($method['settings']['merchant_id']??'')?>"></label><label>Checkout URL<input type="url" name="checkout_url" value="<?=e($method['settings']['checkout_url']??'')?>"></label><label>Secret webhook<input type="password" name="webhook_secret" placeholder="<?=e($method['settings']['secret_masked']?:'Nesetat')?>"><small>Secretul existent nu este afișat și rămâne neschimbat dacă lași gol.</small></label><label>Callback URL<input value="<?=e(config('payments.callback_base').'/'.($method['settings']['provider']??'provider'))?>" readonly></label></div></details><?php elseif($method['key']==='bank_transfer'):?><details><summary>Date bancare</summary><div class="admin-form-grid"><label>Beneficiar<input name="beneficiary" value="<?=e($method['settings']['beneficiary']??'')?>"></label><label>IBAN<input name="iban" value="<?=e($method['settings']['iban']??'')?>"></label><label>Bancă<input name="bank" value="<?=e($method['settings']['bank']??'')?>"></label></div></details><?php endif?><button class="admin-button wide">Salvează metoda</button></form><?php endforeach?></div></section><section class="settings-panel" id="email"><div class="admin-card"><h2>Configurare email</h2><p>Din motive de securitate, datele SMTP se configurează în <code>config/local.php</code> sau ca variabile de mediu pe server. Parola nu este afișată în browser.</p><dl class="settings-status"><dt>Server</dt><dd><?=e(config('mail.host')?:'Neconfigurat')?></dd><dt>Port</dt><dd><?=e(config('mail.port'))?></dd><dt>Expeditor</dt><dd><?=e(config('mail.from_name').' <'.config('mail.from_email').'>')?></dd><dt>Criptare</dt><dd><?=e(config('mail.encryption'))?></dd></dl></div></section><form class="settings-panel" id="seo" action="/admin/setari" method="post"><?=csrf_field()?><section class="admin-card"><h2>SEO general</h2><label>Titlu implicit<input name="seo_title" value="<?=e($settings['seo_title']??'')?>"></label><label>Descriere implicită<textarea name="seo_description" rows="4"><?=e($settings['seo_description']??'')?></textarea></label><p>Sitemap: <a href="/sitemap.xml" target="_blank">/sitemap.xml</a></p><button class="admin-button">Salvează SEO</button></section></form><form class="settings-panel" id="social" action="/admin/setari" method="post"><?=csrf_field()?><section class="admin-card"><h2>Rețele sociale</h2><p>Iconița apare în site doar dacă adresa este completată.</p><div class="admin-form-grid"><?php foreach(['facebook_url'=>'Facebook','instagram_url'=>'Instagram','tiktok_url'=>'TikTok','pinterest_url'=>'Pinterest','youtube_url'=>'YouTube'] as $key=>$label):?><label><?=$label?><input type="url" name="<?=$key?>" value="<?=e($settings[$key]??'')?>"></label><?php endforeach?></div><button class="admin-button">Salvează linkurile</button></section></form>
